package com.portfolio.domain;
import com.portfolio.domain.converter.*; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="HISTORY_RECORD")
public class HistoryRecord {
 @EmbeddedId private HistoryKey id; @Convert(converter=HistoryRecordTypeConverter.class) @Column(name="RECORD_TYPE",columnDefinition="char(2)") private HistoryRecordType recordType; @Convert(converter=HistoryActionConverter.class) @Column(name="ACTION_CODE",columnDefinition="char(1)") private HistoryAction actionCode; @Lob @Column(name="BEFORE_IMAGE") private String beforeImage; @Lob @Column(name="AFTER_IMAGE") private String afterImage; @Column(name="REASON_CODE",columnDefinition="char(4)") private String reasonCode; private LocalDateTime processDate; @Column(length=8) private String processUser;
 public HistoryRecord(){} public HistoryKey getId(){return id;} public void setId(HistoryKey v){id=v;} public HistoryRecordType getRecordType(){return recordType;} public void setRecordType(HistoryRecordType v){recordType=v;} public HistoryAction getActionCode(){return actionCode;} public void setActionCode(HistoryAction v){actionCode=v;} public String getBeforeImage(){return beforeImage;} public void setBeforeImage(String v){beforeImage=v;} public String getAfterImage(){return afterImage;} public void setAfterImage(String v){afterImage=v;} public String getReasonCode(){return reasonCode;} public void setReasonCode(String v){reasonCode=v;} public LocalDateTime getProcessDate(){return processDate;} public void setProcessDate(LocalDateTime v){processDate=v;} public String getProcessUser(){return processUser;} public void setProcessUser(String v){processUser=v;}
}
